package com.starfloat.overlay;
import android.app.*;import android.content.*;import android.graphics.*;import android.media.*;import android.media.projection.*;import android.hardware.display.*;import android.os.*;import android.view.*;import android.widget.*;import java.io.*;
public class FloatingService extends Service {static int projectionResult=0;static Intent projectionData;WindowManager wm;Ball ball;TextView target;WindowManager.LayoutParams bp,tp;long last=0;boolean doubleTap=false;MediaProjection projection;Handler h=new Handler(Looper.getMainLooper());
 public void onCreate(){super.onCreate();if(Build.VERSION.SDK_INT>=26){NotificationChannel ch=new NotificationChannel("sf","StarFloat",NotificationManager.IMPORTANCE_LOW);((NotificationManager)getSystemService(NOTIFICATION_SERVICE)).createNotificationChannel(ch);startForeground(5,new Notification.Builder(this,"sf").setContentTitle("StarFloat active").setContentText("Floating ball is running").setSmallIcon(android.R.drawable.ic_menu_view).build());}wm=(WindowManager)getSystemService(WINDOW_SERVICE);int ty=Build.VERSION.SDK_INT>=26?WindowManager.LayoutParams.TYPE_APPLICATION_OVERLAY:WindowManager.LayoutParams.TYPE_PHONE;target=new TextView(this);target.setText("×  STOP");target.setTextSize(20);target.setGravity(Gravity.CENTER);target.setTextColor(-1);target.setBackgroundColor(0xFFB3261E);tp=new WindowManager.LayoutParams(150,70,ty,WindowManager.LayoutParams.FLAG_NOT_FOCUSABLE,PixelFormat.TRANSLUCENT);tp.gravity=Gravity.BOTTOM|Gravity.CENTER_HORIZONTAL;tp.y=70;wm.addView(target,tp);target.setVisibility(View.GONE);ball=new Ball(this);bp=new WindowManager.LayoutParams(64,64,ty,WindowManager.LayoutParams.FLAG_NOT_FOCUSABLE,PixelFormat.TRANSLUCENT);bp.gravity=Gravity.TOP|Gravity.LEFT;bp.x=240;bp.y=420;wm.addView(ball,bp);registerReceiver(receiver,new IntentFilter("com.starfloat.overlay.UPDATE"),RECEIVER_NOT_EXPORTED);if(projectionData!=null)try{projection=((MediaProjectionManager)getSystemService(MEDIA_PROJECTION_SERVICE)).getMediaProjection(projectionResult,projectionData);}catch(Exception ignored){}}
 BroadcastReceiver receiver=new BroadcastReceiver(){public void onReceive(Context c,Intent i){if(ball!=null)ball.invalidate();}};
 class Ball extends View{Paint p=new Paint(3);Bitmap userImage;String loadedUri="";float sx,sy;int ox,oy;boolean moved;Ball(Context c){super(c);}protected void onDraw(Canvas c){super.onDraw(c);int col=getSharedPreferences("sf",0).getInt("color",0xFFB58CFF),bw=getSharedPreferences("sf",0).getInt("border",3);p.setStyle(Paint.Style.FILL);p.setColor(0xDD11111D);c.drawCircle(getWidth()/2f,getHeight()/2f,getWidth()/2f-2,p);p.setStyle(Paint.Style.STROKE);p.setColor(col);p.setStrokeWidth(bw);c.drawCircle(getWidth()/2f,getHeight()/2f,getWidth()/2f-3,p);p.setStyle(Paint.Style.FILL);String uri=getSharedPreferences("sf",0).getString("image","");if(!uri.equals(loadedUri)){loadedUri=uri;userImage=null;if(!uri.isEmpty())try{java.io.InputStream in=getContentResolver().openInputStream(android.net.Uri.parse(uri));userImage=BitmapFactory.decodeStream(in);if(in!=null)in.close();}catch(Exception ignored){}}if(userImage!=null){int save=c.save();Path clip=new Path();clip.addCircle(getWidth()/2f,getHeight()/2f,getWidth()/2f-5,Path.Direction.CW);c.clipPath(clip);Rect src=new Rect(0,0,userImage.getWidth(),userImage.getHeight());Rect dst=new Rect(5,5,getWidth()-5,getHeight()-5);p.setColor(Color.WHITE);c.drawBitmap(userImage,src,dst,p);c.restoreToCount(save);}else{p.setTextAlign(Paint.Align.CENTER);p.setTextSize(getWidth()*.5f);c.drawText("✦",getWidth()/2f,getHeight()*.66f,p);}}
 public boolean onTouchEvent(android.view.MotionEvent e){if(e.getAction()==0){sx=e.getRawX();sy=e.getRawY();ox=bp.x;oy=bp.y;moved=false;target.setVisibility(View.VISIBLE);return true;}if(e.getAction()==2){int dx=(int)(e.getRawX()-sx),dy=(int)(e.getRawY()-sy);if(Math.abs(dx)+Math.abs(dy)>10)moved=true;if(moved){bp.x=ox+dx;bp.y=oy+dy;wm.updateViewLayout(ball,bp);}return true;}if(e.getAction()==1){target.setVisibility(View.GONE);if(moved){int[] a=new int[2];target.getLocationOnScreen(a);if(e.getRawY()>=a[1]&&e.getRawY()<=a[1]+target.getHeight())stopSelf();return true;}long n=System.currentTimeMillis();if(n-last<350){doubleTap=true;last=0;screenshot();}else{last=n;doubleTap=false;h.postDelayed(()->{if(!doubleTap&&last==n)doPaste();},370);}return true;}return true;}}
 void doPaste(){if(!PasteService.paste())Toast.makeText(this,"Enable Accessibility and focus a text field first",Toast.LENGTH_LONG).show();else Toast.makeText(this,"Paste requested",Toast.LENGTH_SHORT).show();}
 void screenshot(){if(projection==null){Toast.makeText(this,"Open app and grant screenshot permission, then start ball",Toast.LENGTH_LONG).show();return;}try{android.util.DisplayMetrics dm=new android.util.DisplayMetrics();wm.getDefaultDisplay().getRealMetrics(dm);int w=dm.widthPixels,hh=dm.heightPixels;ImageReader ir=ImageReader.newInstance(w,hh,PixelFormat.RGBA_8888,2);VirtualDisplay vd=projection.createVirtualDisplay("StarFloat",w,hh,dm.densityDpi,DisplayManager.VIRTUAL_DISPLAY_FLAG_AUTO_MIRROR,ir.getSurface(),null,h);h.postDelayed(()->{Image im=null;try{im=ir.acquireLatestImage();if(im==null){Toast.makeText(this,"Try double-tapping again",0).show();return;}Image.Plane pl=im.getPlanes()[0];Bitmap bm=Bitmap.createBitmap(pl.getRowStride()/pl.getPixelStride(),hh,Bitmap.Config.ARGB_8888);bm.copyPixelsFromBuffer(pl.getBuffer());Bitmap crop=Bitmap.createBitmap(bm,0,0,w,hh);File f=new File(getExternalFilesDir("Pictures"),"StarFloat_"+System.currentTimeMillis()+".png");FileOutputStream out=new FileOutputStream(f);crop.compress(Bitmap.CompressFormat.PNG,100,out);out.close();bm.recycle();crop.recycle();Toast.makeText(this,"Screenshot saved to StarFloat app storage",Toast.LENGTH_LONG).show();}catch(Exception ex){Toast.makeText(this,"Screenshot failed",0).show();}finally{if(im!=null)im.close();ir.close();vd.release();}},400);}catch(Exception ex){Toast.makeText(this,"Capture failed; re-enable permission",0).show();}}
 public int onStartCommand(Intent i,int f,int id){return START_STICKY;}public IBinder onBind(Intent i){return null;}public void onDestroy(){try{unregisterReceiver(receiver);wm.removeView(ball);wm.removeView(target);}catch(Exception ignored){}if(projection!=null)projection.stop();super.onDestroy();}}
